"""Reproducible teaching content derived from the five supplied History activities.
No pupil identity, original photos, school identity or assessment date in public data.
"""
import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
lessons = []
deep = {}
questions = []

def lesson(slug, icon, title, subtitle, intro, facts, remember, paragraphs, vocab, example, challenge):
    lid = 'h3-' + slug
    lessons.append(dict(id=lid, number=f'{len(lessons)+1:02}', icon=icon, title=title, subtitle=subtitle,
        intro=intro, facts=[dict(term=t,text=s) for t,s in facts], remember=remember,
        tone=['orange','mint','blue','purple'][len(lessons)%4], quizId='history3-'+slug))
    deep[lid] = dict(title=subtitle, paragraphs=paragraphs, vocabulary=vocab, example=example, challenge=challenge)

lesson('diversity','🌍','África: muitas histórias','Um continente diverso, com conhecimentos e governos',
 'A África é um continente, formado por vários países. Seus povos têm diferentes línguas, religiões, culturas e modos de viver. Sua história não começou com a chegada dos europeus.',
 [('Diversidade','existem sociedades com histórias e formas de organização diferentes.'),('Conhecimentos','povos africanos desenvolveram agricultura, comércio, artes e técnicas.'),('Reinos','Congo e Mali são exemplos citados no material.'),('História ampla','estudar apenas a escravidão esconderia grande parte dessa história.')],
 'África é continente. Diversidade significa que seus povos não são todos iguais.',
 ['Um continente reúne países e muitas sociedades. Não devemos falar como se todas as pessoas africanas tivessem uma única cultura.', 'Muito antes do domínio europeu, já havia cidades, reinos, produção de alimentos, trocas e conhecimentos. As pessoas africanas continuam criando e transformando suas sociedades.'],
 [['🌍','Continente','grande porção de terras que reúne países'],['🎨','Diversidade','existência de diferenças entre povos e modos de viver'],['🏛️','Reino','forma de organização política governada por um rei ou uma rainha']],
 'Dizer que toda a África tem uma só língua apaga as diferenças entre seus povos.',
 'Explique por que estudar a África somente pela escravidão conta uma história incompleta. Dê dois exemplos de sua diversidade.')

lesson('origins','🔎','O berço da humanidade','Fósseis ajudam a conhecer o passado',
 'A África é chamada de berço da humanidade porque ali surgiram os primeiros seres humanos. Fósseis encontrados no continente ajudam os pesquisadores a estudar esse passado.',
 [('Berço','a palavra indica origem ou começo nesse contexto.'),('Fósseis','são restos ou vestígios de seres vivos de épocas antigas.'),('Evidências','os pesquisadores estudam descobertas para explicar a história humana.')],
 'Os fósseis são evidências usadas para estudar a origem e a evolução humana.',
 ['Os primeiros seres humanos não deixaram relatos escritos sobre sua origem. Por isso, pesquisadores estudam vestígios materiais, incluindo fósseis.', 'A expressão berço da humanidade se refere à origem humana. Ela não significa que a África seja um país ou que todos os seus povos tenham a mesma história.'],
 [['🔎','Evidência','vestígio que ajuda a sustentar uma explicação'],['🦴','Fóssil','resto ou marca de um ser vivo antigo'],['🌱','Origem','começo de algo']],
 'Um fóssil humano encontrado e estudado ajuda a conhecer seres humanos que viveram há muito tempo.',
 'Por que a África é chamada de berço da humanidade? Que descoberta ajuda a estudar esse passado?')

lesson('slavery','🕊️','Escravidão e falta de liberdade','Regras diferentes não tornavam a escravidão justa',
 'Em algumas sociedades africanas já havia pessoas escravizadas antes do tráfico pelo Atlântico. Isso podia acontecer após guerras ou por dívidas. As situações variavam conforme a sociedade e a época.',
 [('Trabalho','pessoas escravizadas podiam trabalhar em casas ou na agricultura.'),('Variações','em certos casos havia possibilidade de integração à comunidade ou libertação.'),('Liberdade','viver perto de uma família não significava poder escolher a própria vida.'),('Comparação','essas situações não foram idênticas à escravidão colonial no Brasil.')],
 'A escravidão é injusta porque retira a liberdade. Não existiu uma única forma igual em toda a África.',
 ['No material, a escravidão doméstica aparece ligada à casa ou à comunidade de quem dominava a pessoa. Não se deve confundir proximidade com liberdade.', 'Também havia comércio de pessoas escravizadas para outras regiões. O tráfico transatlântico ampliou muito essa exploração e levou milhões de pessoas à força para as Américas.', 'As regras variaram no tempo e no espaço. Evite afirmações como todos eram escravizados, todos trabalhavam em casas ou era igual em todo lugar.'],
 [['🕊️','Liberdade','poder fazer escolhas sobre a própria vida'],['⛓️','Escravização','transformação de uma pessoa em alguém dominado e sem liberdade'],['🏠','Doméstica','ligada à casa ou à comunidade']],
 'Uma pessoa obrigada a trabalhar, sem poder decidir se queria ficar ou sair, não era livre, mesmo vivendo perto da família que a dominava.',
 'Compare escravidão doméstica e venda de pessoas para outras regiões. O que muda? O que as duas situações retiram da pessoa?')

lesson('routes','🧭','Duas rotas, dois espaços','Saara e oceano Atlântico',
 'Transaariano significa através do Saara. Transatlântico significa através do oceano Atlântico. As duas rotas ligavam espaços diferentes e existiram em épocas que, em parte, se sobrepuseram.',
 [('Transaariana','caravanas cruzavam o deserto do Saara, ligando regiões africanas.'),('Circulação','nessas rotas havia sal, ouro e outros produtos; também pessoas escravizadas.'),('Transatlântica','navios levavam africanos à força para as Américas, incluindo o Brasil.'),('Exploração','o tráfico pelo Atlântico alcançou enorme escala e sustentou a exploração colonial.')],
 'Transaariana: Saara e caravanas. Transatlântica: Atlântico e navios.',
 ['Para comparar rotas, observe por onde passavam, como as pessoas eram transportadas e quais regiões eram ligadas.', 'Não é correto afirmar que só mercadorias circulavam nessas rotas. Houve comércio de pessoas escravizadas, uma grave violência contra seres humanos.'],
 [['🏜️','Transaariana','através do deserto do Saara'],['🌊','Transatlântica','através do oceano Atlântico'],['🐪','Caravana','grupo que percorre um trajeto em conjunto']],
 'Caravanas no deserto: rota transaariana. Navios entre África e Américas: rota transatlântica.',
 'Monte uma comparação com três itens: espaço atravessado, transporte e o que ou quem circulava.')

lesson('colonization','📜','Colonização e independências','Uma sequência histórica para compreender',
 'Potências europeias dominaram territórios africanos e os dividiram conforme seus interesses. Muitas divisões desrespeitaram identidades e formas de organização dos povos que já viviam ali.',
 [('Antes','sociedades africanas já produziam conhecimentos e tinham formas de governo.'),('Domínio colonial','colonizadores buscavam controlar territórios, recursos e trabalho.'),('Independências','o material destaca os processos de independência após a Segunda Guerra Mundial.'),('Consequências','a colonização deixou marcas e contribuiu para conflitos.')],
 'A ordem é: sociedades africanas organizadas, colonização europeia, processos de independência.',
 ['A presença de história e de governos africanos vem antes da colonização europeia. Por isso, não faz sentido começar a história africana com a chegada dos colonizadores.', 'Independência significa deixar de estar sob o domínio político de outro país. As diferentes sociedades viveram processos próprios; não ocorreu tudo de uma única vez.'],
 [['🏛️','Colonização','domínio de territórios e povos por uma potência'],['🕊️','Independência','fim do domínio político colonial'],['📜','Sequência histórica','organização de acontecimentos no tempo']],
 'Se uma atividade pede a ordem histórica, primeiro vêm as sociedades já organizadas, depois o domínio europeu e, mais tarde, as independências.',
 'Explique como uma divisão territorial feita sem respeitar os povos locais pode causar problemas.')

lesson('culture','🥁','Cultura afro-brasileira e resistência','Criações, conhecimentos e tradições vivas',
 'A cultura afro-brasileira reúne expressões criadas e preservadas por pessoas negras no Brasil, em diálogo com diferentes tradições africanas e brasileiras.',
 [('Comida','o acarajé é um exemplo trabalhado nas atividades.'),('Música e movimento','berimbau, capoeira, jongo, maracatu e samba de roda aparecem na lista.'),('Memória e religião','história oral, griôs, orixás e povos de terreiro também fazem parte do estudo.'),('Resistência','quilombos e Zumbi dos Palmares remetem às lutas contra a escravidão.')],
 'A contribuição africana está na cultura, nos conhecimentos, no trabalho e nas lutas por direitos.',
 ['Cultura não é só comida ou festa. Inclui palavras, conhecimentos, memórias, literatura, músicas, crenças e maneiras de celebrar.', 'As manifestações afro-brasileiras continuam vivas e se transformam. Devem ser reconhecidas e respeitadas, incluindo suas dimensões religiosas.', 'Quilombos foram espaços de resistência à escravidão. Zumbi dos Palmares é uma referência dessa resistência.'],
 [['🥁','Cultura afro-brasileira','expressões negras formadas na história do Brasil'],['🗣️','História oral','memória transmitida pela fala'],['✊','Resistência','ação contra a dominação e a injustiça'],['🏘️','Quilombo','comunidade ligada à resistência à escravidão']],
 'Acarajé: alimentação e tradição. Berimbau: música ligada à capoeira. Quilombo: resistência.',
 'Escolha duas manifestações e explique sua relação com a cultura afro-brasileira. Depois, cite um exemplo de resistência.')

lesson('diaspora','🌊','Diáspora e formação do Brasil','Contribuições, violência e combate ao racismo',
 'Diáspora é o deslocamento de um povo para diferentes regiões. No estudo, a diáspora africana inclui a retirada forçada de milhões de pessoas da África pelo tráfico transatlântico.',
 [('Forçada','as pessoas eram retiradas de suas terras contra a própria vontade.'),('Estimativas do texto','entre os séculos XVI e XIX, cerca de 12 milhões foram transportados; aproximadamente 40% tiveram o Brasil como destino.'),('Formação do país','africanos e descendentes trabalharam, formaram famílias, resistiram e participaram da construção do Brasil.'),('Reconhecimento','valorizar contribuições exige também lembrar a violência e combater o racismo.')],
 'A contribuição cultural não apaga a violência da escravidão. Reconhecer essa história ajuda a combater o racismo.',
 ['A população brasileira se formou com contribuições de povos indígenas, africanos, europeus e outros grupos. Não se deve reduzir a participação africana ao trabalho na agricultura.', 'Os números do texto são estimativas históricas aproximadas. Para esta revisão, importa compreender a dimensão do deslocamento e o papel do Brasil nesse processo.', 'Africanos e seus descendentes preservaram e criaram culturas, conhecimentos e formas de resistência. Estudar isso não transforma a escravidão em algo positivo ou necessário.'],
 [['🌍','Diáspora','deslocamento de um povo para diferentes regiões'],['🧭','Forçada','feita contra a vontade de quem foi deslocado'],['✊','Racismo','discriminação e desigualdade relacionadas à raça ou à cor']],
 'Conhecer a capoeira e o acarajé é valorizar contribuições. Reconhecer a escravidão e enfrentar o racismo também faz parte desse estudo.',
 'Explique por que precisamos estudar tanto as contribuições culturais quanto a violência da escravidão.')

def q(slug, prompt, answer, wrong, support, hint2, why):
    item = next(l for l in lessons if l['id']=='h3-'+slug)
    idx = len(questions)%4
    opts = [(t, 'Reveja: '+e) for t,e in wrong]
    opts.insert(idx,(answer,why))
    questions.append(dict(id=len(questions)+1, topic=item['title'], prompt=prompt,
       support='Leia com calma e compare as quatro alternativas. Se precisar, você receberá uma pista ao tentar.', hints=[support,hint2],correct='abcd'[idx],
       options=[dict(id='abcd'[i],label=t,explanation=e) for i,(t,e) in enumerate(opts)]))

q('diversity','Por que a África não pode ser chamada de um único país?','Porque é um continente que reúne vários países.', [('Porque é uma cidade.','um continente não é uma cidade.'),('Porque todos falam a mesma língua.','há muitas línguas no continente.'),('Porque não existem governos.','há países e diferentes governos.')], 'Pense na diferença entre país e continente.','Um continente pode reunir muitos países.','Correto. A África reúne vários países e muitos povos.')
q('diversity','Qual exemplo mostra a diversidade africana?','Diferentes línguas, religiões e modos de viver.', [('Uma única cultura em todos os lugares.','as culturas não são todas iguais.'),('Ausência de história antes dos europeus.','já havia sociedades com história.'),('Todos os povos com a mesma organização.','as organizações também variavam.')], 'Diversidade tem relação com diferenças.','Compare línguas e culturas de povos diferentes.','Correto. A diversidade aparece nas línguas, crenças, culturas e formas de organização.')
q('diversity','O que os exemplos dos reinos do Congo e do Mali ajudam a entender?','Que já havia formas de governo e organização na África.', [('Que a história começou na colonização.','esses reinos mostram uma história anterior.'),('Que todos os reinos eram iguais.','os exemplos mostram histórias diferentes.'),('Que não havia comércio.','povos africanos desenvolveram comércio.')], 'Lembre o que existia antes do domínio europeu.','Um reino é uma forma de organização política.','Correto. As sociedades africanas já tinham governos e conhecimentos.')
q('diversity','Estudar a África somente pela escravidão é suficiente?','Não, porque esconderia conhecimentos, culturas e outras histórias.', [('Sim, porque não havia outras atividades.','havia agricultura, artes, comércio e governos.'),('Sim, porque todos tinham a mesma história.','as sociedades têm histórias diversas.'),('Não, porque a escravidão nunca existiu.','a escravidão existiu e precisa ser estudada.')], 'Pense no que ficaria de fora desse estudo.','Agricultura, artes e governos também fazem parte da história.','Correto. Devemos estudar a escravidão dentro de uma história muito mais ampla.')
q('origins','O que significa berço da humanidade?','Lugar de origem dos primeiros seres humanos.', [('Um país com uma única cultura.','a expressão não trata de uma cultura única.'),('Lugar onde começou a colonização europeia.','trata da origem humana.'),('Uma cidade chamada Berço.','é uma expressão sobre a origem.')], 'Berço pode indicar começo.','A expressão se refere à origem humana.','Correto. A África é chamada assim por sua relação com a origem dos primeiros seres humanos.')
q('origins','Que descobertas ajudam a estudar a origem humana na África?','Fósseis de seres humanos antigos.', [('Apenas notícias atuais.','notícias atuais não são vestígios desses seres humanos.'),('Somente mapas coloniais.','os mapas coloniais são muito mais recentes.'),('Apenas anúncios de produtos.','anúncios não comprovam a origem humana.')], 'Busque um vestígio de seres vivos antigos.','Restos ou marcas antigos podem ser preservados.','Correto. Fósseis ajudam a estudar a evolução humana.')
q('origins','Qual é uma atitude de quem pesquisa o passado?','Estudar vestígios e comparar evidências.', [('Inventar respostas sem examinar nada.','uma explicação precisa de evidências.'),('Usar somente a imaginação.','imaginação não substitui evidências.'),('Ignorar todas as descobertas.','descobertas ajudam a pesquisa.')], 'Como podemos sustentar uma explicação?','O pesquisador examina o que foi encontrado.','Correto. Vestígios e evidências ajudam a construir explicações sobre o passado.')
q('origins','Qual frase usa corretamente as ideias estudadas?','A África reúne muitos povos e tem evidências antigas da história humana.', [('A África é um país sem diferenças.','é continente diverso.'),('Ser berço da humanidade significa ter só uma língua.','origem humana não significa cultura única.'),('A história africana começou com os navios europeus.','a história africana é muito anterior.')], 'Junte origem humana e diversidade.','Uma mesma região pode ter uma história antiga e muitos povos diferentes.','Correto. A origem humana e a diversidade são ideias compatíveis.')
q('slavery','O que podia levar à escravização em algumas sociedades africanas?','Guerras ou dívidas, conforme o lugar e a época.', [('Escolher livremente um emprego.','escravidão envolve falta de liberdade.'),('Todas as pessoas terem a mesma cultura.','isso não explica a escravização.'),('Somente a chegada dos europeus.','já havia formas anteriores de escravidão.')], 'Lembre os exemplos de situações do material.','Prisioneiros de guerra e pessoas com dívidas são exemplos citados.','Correto. As regras variavam entre sociedades e épocas.')
q('slavery','Viver perto da família que dominava a pessoa significava ser livre?','Não, pois ela não podia escolher livremente sua vida.', [('Sim, a proximidade garantia liberdade.','proximidade não significa liberdade.'),('Sim, toda escravidão era um trabalho escolhido.','não era uma escolha livre.'),('Sim, trabalhar em casa nunca pode ser forçado.','o trabalho doméstico também podia ser imposto.')], 'Observe se a pessoa podia fazer suas próprias escolhas.','Estar perto de uma família não garante o direito de sair ou decidir.','Correto. Integração ou proximidade não apagavam a falta de liberdade.')
q('slavery','Qual afirmação evita uma generalização errada?','As regras da escravidão variavam entre sociedades e épocas.', [('Tudo era igual em toda a África.','existiam diferenças.'),('Todas as pessoas trabalhavam em casas.','também havia trabalho agrícola e outras situações.'),('Era idêntica à escravidão colonial brasileira.','as situações históricas não eram idênticas.')], 'Cuidado com palavras como todos e sempre.','O material destaca variações conforme lugar e época.','Correto. A diversidade também precisa ser considerada no estudo da escravidão.')
q('slavery','Qual diferença aparece na comparação proposta pelo material?','Na escravidão doméstica havia vínculo com a casa ou comunidade; no comércio para outras regiões, pessoas eram vendidas e deslocadas.', [('Na doméstica todos eram livres.','não tinham liberdade para escolher sua vida.'),('No comércio as pessoas viajavam sempre por vontade própria.','eram tratadas como mercadoria e forçadas.'),('As duas situações eram passeios.','ambas envolviam dominação e violência.')], 'Compare permanência na comunidade e deslocamento.','A mudança de região não torna nenhuma das situações justa.','Correto. Há diferenças, mas ambas retiravam a liberdade das pessoas.')
q('routes','Qual associação está correta?','Transaariana: deserto do Saara e caravanas.', [('Transaariana: oceano Pacífico e aviões.','o nome se refere ao Saara.'),('Transatlântica: deserto do Saara e caravanas.','essa associação é transaariana.'),('Transaariana: somente cidades brasileiras.','ligava regiões através do Saara.')], 'Encontre Saara no nome da rota.','Caravanas cruzavam o deserto.','Correto. A rota transaariana atravessava o Saara.')
q('routes','Como milhões de africanos foram levados à força para as Américas?','Em navios pela rota transatlântica.', [('Em caravanas pelo Saara até o Brasil.','a travessia até as Américas era marítima.'),('Em aviões no século XVI.','o transporte citado é o navio.'),('Em viagens de férias escolhidas.','o deslocamento foi forçado.')], 'Qual oceano separa África e Américas?','Transatlântico significa através do Atlântico.','Correto. Navios atravessavam o Atlântico levando pessoas escravizadas.')
q('routes','Só mercadorias circulavam nas rotas estudadas?','Não. Também houve comércio de pessoas escravizadas.', [('Sim, apenas ouro.','também circulavam sal, outros produtos e pessoas escravizadas.'),('Sim, apenas alimentos.','o texto também trata do comércio de pessoas.'),('Não havia nenhuma circulação.','as rotas ligavam regiões e movimentavam produtos e pessoas.')], 'Lembre a violência descrita no material.','As rotas também foram usadas para deslocar pessoas sem liberdade.','Correto. Seres humanos foram tratados como mercadoria, uma grave violência.')
q('routes','Qual comparação distingue as duas rotas?','Uma cruzava o Saara; a outra, o oceano Atlântico.', [('As duas cruzavam somente o mesmo deserto.','a transatlântica era marítima.'),('Uma existiu apenas depois de a outra acabar.','suas épocas se sobrepuseram em parte.'),('As duas usavam somente aviões.','o material apresenta caravanas e navios.')], 'Compare os espaços atravessados.','Uma rota é associada a deserto e a outra a oceano.','Correto. As rotas passavam por espaços diferentes e suas épocas se sobrepuseram em parte.')
q('colonization','Qual é a sequência histórica correta?','Sociedades africanas organizadas → colonização europeia → processos de independência.', [('Independência → colonização → primeiras sociedades.','as sociedades já existiam antes do domínio europeu.'),('Colonização → independência → começo de toda a história africana.','a história africana começou muito antes.'),('Independência → primeiras sociedades → colonização.','essa ordem coloca a independência antes do domínio colonial.')], 'O que já existia antes da chegada dos colonizadores?','As sociedades africanas tinham conhecimentos e governos antes da colonização.','Correto. Essa sequência reconhece a história africana anterior ao domínio europeu.')
q('colonization','A divisão colonial dos territórios respeitou sempre os povos locais?','Não. Muitas divisões seguiram interesses dos colonizadores.', [('Sim, todas as identidades foram respeitadas.','o material destaca o desrespeito a identidades.'),('Sim, só os povos locais tomaram as decisões.','potências europeias impuseram seus interesses.'),('Não havia povos vivendo ali.','já havia sociedades organizadas.')], 'Pense em quem controlava as decisões coloniais.','Os interesses das potências europeias orientavam as divisões.','Correto. Fronteiras impostas podiam desrespeitar os povos e contribuir para conflitos.')
q('colonization','O que significa independência nesse estudo?','Deixar de estar sob o domínio político colonial.', [('Passar a obedecer a outra potência.','isso mantém uma forma de dominação.'),('Apagar a história anterior.','a história permanece.'),('Todos os povos passarem a ter uma só cultura.','independência não elimina a diversidade.')], 'Independência se relaciona ao fim de uma dominação.','Pense em decidir o próprio governo sem o controle colonial.','Correto. É a saída do domínio político colonial.')
q('colonization','Que período o material destaca para os processos de independência?','Após a Segunda Guerra Mundial.', [('Antes de existirem sociedades africanas.','as sociedades são muito anteriores.'),('Somente antes de surgir a humanidade.','não faz sentido histórico.'),('Apenas antes de qualquer colonização.','a independência vem após o domínio colonial.')], 'Lembre o marco histórico citado no texto.','O texto menciona uma guerra mundial e o período posterior a ela.','Correto. O material destaca as independências no período após a Segunda Guerra Mundial.')
q('culture','Qual conjunto traz exemplos de cultura afro-brasileira do material?','Acarajé, capoeira e samba de roda.', [('Somente moedas e senhas.','esses não são os exemplos culturais trabalhados.'),('Somente mapas de fronteiras.','o estudo cultural apresenta comida, música e outras expressões.'),('Somente fósseis humanos.','fósseis se relacionam à origem humana.')], 'Pense em comida, movimento e música.','A atividade apresenta um vocabulário da cultura afro-brasileira.','Correto. São expressões citadas nas atividades.')
q('culture','A cultura afro-brasileira inclui apenas alimentos?','Não. Inclui músicas, conhecimentos, memórias, crenças e outras expressões.', [('Sim, não há contribuições em outras áreas.','há muitas outras expressões.'),('Sim, música não faz parte de cultura.','música é uma expressão cultural.'),('Não, porque nenhuma comida faz parte da cultura.','comidas também integram tradições culturais.')], 'Lembre a variedade do vocabulário estudado.','Berimbau, história oral e povos de terreiro aparecem na lista.','Correto. A contribuição cultural é ampla e continua viva.')
q('culture','Qual relação entre quilombos e Zumbi dos Palmares aparece na revisão?','Resistência à escravidão.', [('Defesa da falta de liberdade.','a resistência enfrentava a dominação.'),('Somente venda de mercadorias.','essa não é a relação estudada.'),('Origem dos fósseis humanos.','fósseis pertencem a outro tema.')], 'Pense nas lutas contra a dominação.','A palavra resistência ajuda a fazer a associação.','Correto. Quilombos e Zumbi são referências de resistência à escravidão.')
q('culture','O que é história oral?','Transmissão de memórias e conhecimentos pela fala.', [('Uma cultura sem memória.','a oralidade preserva e transmite memória.'),('Somente um documento digitado.','a característica é a transmissão oral.'),('Um tipo de transporte marítimo.','não é um meio de transporte.')], 'Oral está relacionado à fala.','Pense em histórias e saberes passados entre gerações por meio de relatos.','Correto. A fala pode transmitir histórias, memórias e conhecimentos.')
q('diaspora','O que significa diáspora?','Deslocamento de um povo para diferentes regiões.', [('Criação de um reino em um só lugar.','a ideia é dispersão ou deslocamento.'),('Somente uma compra de produtos.','não define movimento de um povo.'),('União de todos em um só país.','a diáspora envolve diferentes regiões.')], 'Pense no movimento de pessoas.','Um povo passa a viver em diferentes lugares.','Correto. Diáspora é o deslocamento de um povo para diferentes regiões.')
q('diaspora','Por que a diáspora africana estudada é chamada de forçada?','Porque pessoas foram retiradas de suas terras contra a própria vontade.', [('Porque escolheram viajar de férias.','não se tratou de turismo.'),('Porque todas receberam convites e puderam recusar.','não havia escolha livre.'),('Porque não existiam famílias na África.','as pessoas tinham famílias e comunidades.')], 'Observe se havia liberdade para escolher.','O tráfico arrancava pessoas de suas terras.','Correto. Milhões foram deslocados sem poder decidir livremente.')
q('diaspora','Que estimativas o texto apresenta para o tráfico transatlântico?','Cerca de 12 milhões de pessoas; aproximadamente 40% destinadas ao Brasil.', [('12 pessoas; 100% destinadas ao Brasil.','a escala foi de milhões e o Brasil não foi o único destino.'),('12 milhões; nenhuma destinada ao Brasil.','o Brasil recebeu uma grande parcela.'),('Apenas mil pessoas; 1% destinadas ao Brasil.','não são as estimativas apresentadas.')], 'Os valores são aproximados e mostram a dimensão da violência.','Lembre: milhões de pessoas e uma grande parcela destinada ao Brasil.','Correto. São estimativas históricas apresentadas no material, entre os séculos XVI e XIX.')
q('diaspora','Qual atitude reúne as duas ideias centrais do estudo?','Valorizar as contribuições africanas, lembrar a violência e combater o racismo.', [('Valorizar as festas e esquecer a escravidão.','as contribuições não apagam a violência.'),('Afirmar que africanos não participaram da formação do Brasil.','a participação foi profunda.'),('Dizer que a violência foi necessária para criar cultura.','a criação cultural não justifica a escravidão.')], 'Não deixe de lado nem as contribuições nem os direitos das pessoas.','Reconhecimento cultural e combate ao racismo precisam caminhar juntos.','Correto. Estudar contribuições e violência ajuda a compreender a história e enfrentar o racismo.')

